-- ============================================
-- LUMA — Thème 15 : MOYEN 3/3 x4 — Un imprévu météo à gérer
-- ============================================


update scenarios set content = '{"characters": {"alice": "Alice", "cafe_owner": "le propriétaire du café"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alice", "text": "(Sudden downpour) Well, this is very London of the weather, isn''t it?", "text_fr": "(Averse soudaine) Bon, c''est très londonien de la part de la météo, non ?", "choices": [{"text": "Ha, typical! Should we find shelter somewhere nearby?", "text_fr": "Ha, typique ! On devrait trouver un abri à proximité ?", "next": "n2"}, {"text": "Let''s just push through it, we still have places to see!", "text_fr": "Continuons à travers, on a encore des endroits à voir !", "next": "n2b"}]}, "n2": {"speaker": "alice", "text": "There''s a cute little café just across the street, let''s duck in there.", "text_fr": "Il y a un joli petit café juste en face, réfugions-nous là-dedans.", "choices": [{"text": "Perfect, we can wait out the rain with some tea.", "text_fr": "Parfait, on peut attendre que la pluie passe avec du thé.", "next": "n3"}]}, "n2b": {"speaker": "alice", "text": "Ha, that''s the spirit! Though we might end up looking like drowned rats.", "text_fr": "Ha, voilà l''esprit ! Même si on va peut-être finir trempés comme des soupes.", "choices": [{"text": "Worth it for the adventure, honestly!", "text_fr": "Ça vaut le coup pour l''aventure, honnêtement !", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(After a few soggy minutes, you both decide shelter is the smarter option after all.)", "text_fr": "(Après quelques minutes trempées, vous décidez tous les deux que l''abri est finalement la meilleure option.)", "choices": [{"text": "Okay, let''s find that café you mentioned.", "text_fr": "D''accord, cherchons ce café dont tu parlais.", "next": "n4"}]}, "n4": {"speaker": "cafe_owner", "text": "Terrible weather out there today! Come in, warm up with some tea.", "text_fr": "Météo terrible dehors aujourd''hui ! Entrez, réchauffez-vous avec du thé.", "choices": [{"text": "Thank you, this is exactly what we needed right now.", "text_fr": "Merci, c''est exactement ce dont on avait besoin maintenant.", "next": "n5"}]}, "n5": {"speaker": "alice", "text": "You know, this unplanned stop is honestly turning into a really nice moment.", "text_fr": "Tu sais, cet arrêt imprévu se transforme honnêtement en un très joli moment.", "choices": [{"text": "It really is. Sometimes the best memories come from these little detours.", "text_fr": "C''est vraiment le cas. Parfois les meilleurs souvenirs viennent de ces petits détours.", "next": "n6"}]}, "n6": {"speaker": "you_thought", "text": "(Looking outside, you notice the rain finally beginning to ease up.)", "text_fr": "(En regardant dehors, vous remarquez que la pluie commence enfin à se calmer.)", "choices": [{"text": "Looks like it''s clearing up — ready to continue exploring?", "text_fr": "On dirait que ça s''éclaircit — prête à continuer l''exploration ?", "next": "n7"}]}, "n7": {"speaker": "alice", "text": "Definitely! Though I''m almost sad to leave this cozy spot now.", "text_fr": "Définitivement ! Même si je suis presque triste de quitter cet endroit douillet maintenant.", "choices": [{"text": "We can always come back later if we want more tea!", "text_fr": "On peut toujours revenir plus tard si on veut plus de thé !", "next": "end_adapted"}]}, "end_adapted": {"speaker": "alice", "text": "True! Onward then, rain or shine, this city has more to show us.", "text_fr": "Vrai ! En avant alors, pluie ou soleil, cette ville a encore plus à nous montrer.", "end": true, "ending_label": "Imprévu météo transformé en joli moment 🌧️☕"}}}'::jsonb, is_playable = true
where title = 'Un imprévu météo à gérer'
  and theme_id = (select id from scenario_themes where position = 15 and language_id = (select id from languages where code = 'en'));
